add(tab(['Book','t full VaR 1%','t second-order VaR 1%','t full ES 1%','t second-order ES 1%'],[[name,f(v['simulated']['student_t']['1%']['VaR'],2),f(v['simulated']['student_t']['gamma_approx']['0.01']['VaR'],2),f(v['simulated']['student_t']['1%']['ES'],2),f(v['simulated']['student_t']['gamma_approx']['0.01']['ES'],2)] for name,v in b.items()]))
def ratio(v,model,lv):
 q=v['simulated'][model][lv];return q['ES']/q['VaR']
def chg(v,lv,z):
 return v['simulated']['student_t'][lv][z]/v['simulated']['normal'][lv][z]-1
add(tab(['Book','ES/VaR 5% normal','ES/VaR 5% t','Flat-price P&L','Simulated mean (t)','t vs normal: VaR 5%','VaR 1%','ES 1%'],[[name,f(ratio(v,'normal','5%'),2),f(ratio(v,'student_t','5%'),2),f(v['flat_price_pnl'],2),f(v['simulated']['student_t']['mean'],2),pct(chg(v,'5%','VaR'),1),pct(chg(v,'1%','VaR'),1),pct(chg(v,'1%','ES'),1)] for name,v in b.items()]))
ss=b['ShortStraddle'];hs=b['HedgedShortCall']
add(f'<p>The ES/VaR prediction held. Under the t, the short straddle ({f(ratio(ss,"student_t","5%"),2)}) and the hedged short call ({f(ratio(hs,"student_t","5%"),2)}) are well above 1.25, while the two delta-dominated books stay much closer to it. The sign prediction also held: all four books gain if the price does not move. But the simulated mean is far smaller than the flat-price P&L for the short gamma books (short straddle: {f(ss["flat_price_pnl"],2)} if flat versus a mean of {f(ss["simulated"]["student_t"]["mean"],2)}), because the theta gain is mostly offset by gamma losses whenever ABC moves. The positive mean that remains is the premium for selling convexity: it pays for the rare large losses in the left tail, as the ES numbers show. It is not a free return.</p>')
add(f'<p>Switching from the normal to the t moves the deep-tail numbers of the short gamma books the most. For example, 1% ES rises {pct(chg(ss,"1%","ES"),1)} for the short straddle and {pct(chg(hs,"1%","ES"),1)} for the hedged short call. Their P&L is quadratic in ΔS, so the fatter tails of the t are amplified, and ES averages the whole tail beyond the quantile. The 5% VaR moves least (only {pct(chg(ss,"5%","VaR"),1)} for the short straddle). A t fitted to the same data has a similar spread near the 5% quantile, because its lower scale compensates for its heavier tails there. The two laws mostly differ beyond that point.</p>')
add('<p>A reply to the “flat” claim: “The hedge removes only the local stock delta; it does not remove negative gamma or time decay. A large price move over ten days can cause a substantial loss, especially in the tail.”</p>')
