 cap=v['models']['CAPM']['coefficients']['const'];four=v['models']['Carhart4']['coefficients']['const'];bet=v['models']['Carhart4']['coefficients'];prem=p['sample_factor_mean_daily'];factor=sum(bet[z]*prem[z] for z in ['SMB','HML','Mom'])
